export function slugify(input, options = {}) {
  const separator = options.separator === undefined ? "-" : options.separator;
  if (typeof separator !== "string" || separator.length === 0) {
    throw new TypeError("options.separator must be a non-empty string");
  }

  const maxLength = options.maxLength;
  if (
    maxLength !== undefined &&
    (!Number.isInteger(maxLength) || maxLength <= 0)
  ) {
    throw new TypeError("options.maxLength must be a positive integer");
  }

  const normalized = String(input)
    .normalize("NFKD")
    .replace(/\p{M}/gu, "")
    .toLowerCase();

  let slug = normalized
    .split(/[^\p{L}\p{N}]+/u)
    .filter(Boolean)
    .join(separator);

  if (maxLength !== undefined && slug.length > maxLength) {
    let cut = slug.slice(0, maxLength);
    if (slug[maxLength] !== separator[0]) {
      const index = cut.lastIndexOf(separator);
      if (index > 0) {
        cut = cut.slice(0, index);
      }
    }
    while (cut.endsWith(separator)) {
      cut = cut.slice(0, -separator.length);
    }
    slug = cut;
  }

  return slug;
}
